    29  /**
    30   * Check if the place matches the search by the place name or description.
    31   * @param search The search string for a place
    32   * @param place The place to check for a match on the search
    33   * @returns true if search is related to place, otherwise it returns false.
    34   */
    35  function isPlaceMatchForSearch(search: string, place: PredefinedPlace): boolean {
    36      if (!search) {
    37          return true;
    38      }
    39      if (!place) {
    40          return false;
    41      }
    42      const fullSearchSentence = `${place.name ?? ''} ${place.description}`;
    43      return search.split(' ').every((searchTerm) => !searchTerm || fullSearchSentence.toLocaleLowerCase().includes(searchTerm.toLocaleLowerCase()));
    44  }
