    51  function AddressSearch(
    52      {
    53          canUseCurrentLocation = false,
    54          containerStyles,
    55          defaultValue,
    56          errorText = '',
    57          hint = '',
    58          inputID,
    59          isLimitedToUSA = false,
    60          label,
    61          maxInputLength,
    62          onFocus,
    63          onBlur,
    64          onInputChange,
    65          onPress,
    66          predefinedPlaces = [],
    67          preferredLocale,
    68          renamedInputKeys = {
    69              street: 'addressStreet',
    70              street2: 'addressStreet2',
    71              city: 'addressCity',
    72              state: 'addressState',
    73              zipCode: 'addressZipCode',
    74              lat: 'addressLat',
    75              lng: 'addressLng',
    76          },
    77          resultTypes = 'address',
    78          shouldSaveDraft = false,
    79          value,
    80          locationBias,
    81      }: AddressSearchProps,
    82      ref: ForwardedRef<HTMLElement>,
    83  ) {
    84      const theme = useTheme();
    85      const styles = useThemeStyles();
    86      const StyleUtils = useStyleUtils();
    87      const {translate} = useLocalize();
    88      const {isOffline} = useNetwork();
    89      const [displayListViewBorder, setDisplayListViewBorder] = useState(false);
    90      const [isTyping, setIsTyping] = useState(false);
    91      const [isFocused, setIsFocused] = useState(false);
    92      // eslint-disable-next-line @typescript-eslint/prefer-nullish-coalescing
    93      const [searchValue, setSearchValue] = useState('');
    94      const [locationErrorCode, setLocationErrorCode] = useState<GeolocationErrorCodeType>(null);
    95      const [isFetchingCurrentLocation, setIsFetchingCurrentLocation] = useState(false);
    96      const shouldTriggerGeolocationCallbacks = useRef(true);
    97      const [shouldHidePredefinedPlaces, setShouldHidePredefinedPlaces] = useState(false);
    98      const containerRef = useRef<View>(null);
    99      const query = useMemo(
   100          () => ({
   101              language: preferredLocale,
   102              types: resultTypes,
   103              components: isLimitedToUSA ? 'country:us' : undefined,
   104              ...(locationBias && {locationbias: locationBias}),
   105          }),
   106          [preferredLocale, resultTypes, isLimitedToUSA, locationBias],
   107      );
   108      const shouldShowCurrentLocationButton = canUseCurrentLocation && searchValue.trim().length === 0 && isFocused;
   109      const saveLocationDetails = (autocompleteData: GooglePlaceData, details: GooglePlaceDetail | null) => {
   110          const addressComponents = details?.address_components;
   111          if (!addressComponents) {
   112              // When there are details, but no address_components, this indicates that some predefined options have been passed
   113              // to this component which don't match the usual properties coming from auto-complete. In that case, only a limited
   114              // amount of data massaging needs to happen for what the parent expects to get from this function.
   115              if (details) {
   116                  onPress?.({
   117                      address: autocompleteData.description ?? '',
   118                      lat: details.geometry.location.lat ?? 0,
   119                      lng: details.geometry.location.lng ?? 0,
   120                  });
   121              }
   122              return;
   123          }
   124
   125          // Gather the values from the Google details
   126          const {
   127              street_number: streetNumber,
   128              route: streetName,
   129              subpremise,
   130              locality,
   131              sublocality,
   132              postal_town: postalTown,
   133              postal_code: zipCode,
   134              administrative_area_level_1: state,
   135              administrative_area_level_2: stateFallback,
   136              country: countryPrimary,
   137          } = GooglePlacesUtils.getAddressComponents(addressComponents, {
   138              // eslint-disable-next-line @typescript-eslint/naming-convention
   139              street_number: 'long_name',
   140              route: 'long_name',
   141              subpremise: 'long_name',
   142              locality: 'long_name',
   143              sublocality: 'long_name',
   144              // eslint-disable-next-line @typescript-eslint/naming-convention
   145              postal_town: 'long_name',
   146              // eslint-disable-next-line @typescript-eslint/naming-convention
   147              postal_code: 'long_name',
   148              // eslint-disable-next-line @typescript-eslint/naming-convention
   149              administrative_area_level_1: 'short_name',
   150              // eslint-disable-next-line @typescript-eslint/naming-convention
   151              administrative_area_level_2: 'long_name',
   152              country: 'short_name',
   153          });
   154
   155          // The state's iso code (short_name) is needed for the StatePicker component but we also
   156          // need the state's full name (long_name) when we render the state in a TextInput.
   157          const {administrative_area_level_1: longStateName} = GooglePlacesUtils.getAddressComponents(addressComponents, {
   158              // eslint-disable-next-line @typescript-eslint/naming-convention
   159              administrative_area_level_1: 'long_name',
   160          });
   161
   162          // Make sure that the order of keys remains such that the country is always set above the state.
   163          // Refer to https://github.com/Expensify/App/issues/15633 for more information.
   164          const {
   165              country: countryFallbackLongName = '',
   166              state: stateAutoCompleteFallback = '',
   167              city: cityAutocompleteFallback = '',
   168          } = GooglePlacesUtils.getPlaceAutocompleteTerms(autocompleteData?.terms ?? []);
   169
   170          const countryFallback = Object.keys(CONST.ALL_COUNTRIES).find((country) => country === countryFallbackLongName);
   171
   172          // eslint-disable-next-line @typescript-eslint/prefer-nullish-coalescing
   173          const country = countryPrimary || countryFallback || '';
   174
   175          const values = {
   176              street: `${streetNumber} ${streetName}`.trim(),
   177              // Autocomplete returns any additional valid address fragments (e.g. Apt #) as subpremise.
   178              street2: subpremise,
   179              // Make sure country is updated first, since city and state will be reset if the country changes
   180              country: '',
   181              state: state || stateAutoCompleteFallback,
   182              // When locality is not returned, many countries return the city as postalTown (e.g. 5 New Street
   183              // Square, London), otherwise as sublocality (e.g. 384 Court Street Brooklyn). If postalTown is
   184              // returned, the sublocality will be a city subdivision so shouldn't take precedence (e.g.
   185              // Salagatan, Upssala, Sweden).
   186              city: locality || postalTown || sublocality || cityAutocompleteFallback,
   187              zipCode,
   188
   189              lat: details.geometry.location.lat ?? 0,
   190              lng: details.geometry.location.lng ?? 0,
   191              address: autocompleteData.description || details.formatted_address || '',
   192          };
   193
   194          // If the address is not in the US, use the full length state name since we're displaying the address's
   195          // state / province in a TextInput instead of in a picker.
   196          if (country !== CONST.COUNTRY.US) {
   197              values.state = longStateName;
   198          }
   199
   200          // UK addresses return countries (e.g. England) in the state field (administrative_area_level_1)
   201          // So we use a secondary field (administrative_area_level_2) as a fallback
   202          if (country === CONST.COUNTRY.GB) {
   203              values.state = stateFallback;
   204          }
   205
   206          // Set the state to be the same as the city in case the state is empty.
   207          if (!values.state) {
   208              values.state = values.city;
   209          }
   210
   211          // Some edge-case addresses may lack both street_number and route in the API response, resulting in an empty "values.street"
   212          // We are setting up a fallback to ensure "values.street" is populated with a relevant value
   213          if (!values.street && details.adr_address) {
   214              const streetAddressRegex = /<span class="street-address">([^<]*)<\/span>/;
   215              const adrAddress = details.adr_address.match(streetAddressRegex);
   216              const streetAddressFallback = adrAddress ? adrAddress?.[1] : null;
   217              if (streetAddressFallback) {
   218                  values.street = streetAddressFallback;
   219              }
   220          }
   221
   222          // Not all pages define the Address Line 2 field, so in that case we append any additional address details
   223          // (e.g. Apt #) to Address Line 1
   224          if (subpremise && typeof renamedInputKeys?.street2 === 'undefined') {
   225              values.street += `, ${subpremise}`;
   226          }
   227
   228          const isValidCountryCode = !!Object.keys(CONST.ALL_COUNTRIES).find((foundCountry) => foundCountry === country);
   229          if (isValidCountryCode) {
   230              values.country = country;
   231          }
   232
   233          if (inputID) {
   234              Object.entries(values).forEach(([key, inputValue]) => {
   235                  const inputKey = renamedInputKeys?.[key as keyof Omit<Address, 'current'>] ?? key;
   236                  if (!inputKey) {
   237                      return;
   238                  }
   239                  onInputChange?.(inputValue, inputKey);
   240              });
   241          } else {
   242              onInputChange?.(values);
   243          }
   244
   245          onPress?.(values);
   246      };
   247
   248      /** Gets the user's current location and registers success/error callbacks */
   249      const getCurrentLocation = () => {
   250          if (isFetchingCurrentLocation) {
   251              return;
   252          }
   253
   254          setIsTyping(false);
   255          setIsFocused(false);
   256          setDisplayListViewBorder(false);
   257          setIsFetchingCurrentLocation(true);
   258
   259          Keyboard.dismiss();
   260
   261          getCurrentPosition(
   262              (successData) => {
   263                  if (!shouldTriggerGeolocationCallbacks.current) {
   264                      return;
   265                  }
   266
   267                  setIsFetchingCurrentLocation(false);
   268                  setLocationErrorCode(null);
   269
   270                  const {latitude, longitude} = successData.coords;
   271
   272                  const location = {
   273                      lat: latitude,
   274                      lng: longitude,
   275                      address: CONST.YOUR_LOCATION_TEXT,
   276                      name: CONST.YOUR_LOCATION_TEXT,
   277                  };
   278
   279                  // Update the current user location
   280                  UserLocation.setUserLocation({longitude, latitude});
   281                  onPress?.(location);
   282              },
   283              (errorData) => {
   284                  if (!shouldTriggerGeolocationCallbacks.current) {
   285                      return;
   286                  }
   287
   288                  setIsFetchingCurrentLocation(false);
   289                  setLocationErrorCode(errorData?.code ?? null);
   290              },
   291              {
   292                  maximumAge: 0, // No cache, always get fresh location info
   293                  timeout: 30000,
   294              },
   295          );
   296      };
   297
   298      const renderHeaderComponent = () => (
   299          // eslint-disable-next-line react/jsx-no-useless-fragment
   300          <>
   301              {(predefinedPlaces?.length ?? 0) > 0 && (
   302                  <View style={styles.overflowAuto}>
   303                      {/* This will show current location button in list if there are some recent destinations */}
   304                      {shouldShowCurrentLocationButton && (
   305                          <CurrentLocationButton
   306                              onPress={getCurrentLocation}
   307                              isDisabled={isOffline}
   308                          />
   309                      )}
   310                      {!value && <Text style={[styles.textLabel, styles.colorMuted, styles.pv2, styles.ph3, styles.overflowAuto]}>{translate('common.recentDestinations')}</Text>}
   311                  </View>
   312              )}
   313          </>
   314      );
   315
   316      // eslint-disable-next-line arrow-body-style
   317      useEffect(() => {
   318          return () => {
   319              // If the component unmounts we don't want any of the callback for geolocation to run.
   320              shouldTriggerGeolocationCallbacks.current = false;
   321          };
   322      }, []);
   323
   324      const filteredPredefinedPlaces = useMemo(() => {
   325          if (!searchValue) {
   326              return predefinedPlaces ?? [];
   327          }
   328          if (shouldHidePredefinedPlaces) {
   329              return [];
   330          }
   331          return predefinedPlaces?.filter((predefinedPlace) => isPlaceMatchForSearch(searchValue, predefinedPlace)) ?? [];
   332      }, [predefinedPlaces, searchValue, shouldHidePredefinedPlaces]);
   333
   334      const listEmptyComponent = useMemo(
   335          () => (!isTyping ? undefined : <Text style={[styles.textLabel, styles.colorMuted, styles.pv4, styles.ph3, styles.overflowAuto]}>{translate('common.noResultsFound')}</Text>),
   336          [isTyping, styles, translate],
   337      );
   338
   339      const listLoader = useMemo(
   340          () => (
   341              <View style={[styles.pv4]}>
   342                  <ActivityIndicator
   343                      color={theme.spinner}
   344                      size="small"
   345                  />
   346              </View>
   347          ),
   348          [styles.pv4, theme.spinner],
   349      );
   350
   351      return (
   352          /*
   353           * The GooglePlacesAutocomplete component uses a VirtualizedList internally,
   354           * and VirtualizedLists cannot be directly nested within other VirtualizedLists of the same orientation.
   355           * To work around this, we wrap the GooglePlacesAutocomplete component with a horizontal ScrollView
   356           * that has scrolling disabled and would otherwise not be needed
   357           */
   358          <>
   359              <ScrollView
   360                  horizontal
   361                  contentContainerStyle={styles.flex1}
   362                  scrollEnabled={false}
   363                  // keyboardShouldPersistTaps="always" is required for Android native,
   364                  // otherwise tapping on a result doesn't do anything. More information
   365                  // here: https://github.com/FaridSafi/react-native-google-places-autocomplete#use-inside-a-scrollview-or-flatlist
   366                  keyboardShouldPersistTaps="always"
   367              >
   368                  <View
   369                      style={styles.w100}
   370                      ref={containerRef}
   371                  >
   372                      <GooglePlacesAutocomplete
   373                          disableScroll
   374                          fetchDetails
   375                          suppressDefaultStyles
   376                          enablePoweredByContainer={false}
   377                          predefinedPlaces={filteredPredefinedPlaces}
   378                          listEmptyComponent={listEmptyComponent}
   379                          listLoaderComponent={listLoader}
   380                          renderHeaderComponent={renderHeaderComponent}
   381                          onPress={(data, details) => {
   382                              saveLocationDetails(data, details);
   383                              setIsTyping(false);
   384
   385                              // After we select an option, we set displayListViewBorder to false to prevent UI flickering
   386                              setDisplayListViewBorder(false);
   387                              setIsFocused(false);
   388
   389                              // Clear location error code after address is selected
   390                              setLocationErrorCode(null);
   391                          }}
   392                          query={query}
   393                          requestUrl={{
   394                              useOnPlatform: 'all',
   395                              url: isOffline ? '' : ApiUtils.getCommandURL({command: 'Proxy_GooglePlaces?proxyUrl='}),
   396                          }}
   397                          textInputProps={{
   398                              InputComp: TextInput,
   399                              ref,
   400                              label,
   401                              containerStyles,
   402                              errorText,
   403                              hint: displayListViewBorder || (predefinedPlaces?.length === 0 && shouldShowCurrentLocationButton) || (canUseCurrentLocation && isTyping) ? undefined : hint,
   404                              value,
   405                              defaultValue,
   406                              inputID,
   407                              shouldSaveDraft,
   408                              onFocus: () => {
   409                                  setIsFocused(true);
   410                                  onFocus?.();
   411                              },
   412                              onBlur: (event) => {
   413                                  if (!isCurrentTargetInsideContainer(event, containerRef)) {
   414                                      setDisplayListViewBorder(false);
   415                                      setIsFocused(false);
   416                                      setIsTyping(false);
