   431                                  if (!text && !predefinedPlaces?.length) {
   432                                      setDisplayListViewBorder(false);
   433                                  }
   434                              },
   435                              maxLength: maxInputLength,
   436                              spellCheck: false,
   437                              selectTextOnFocus: true,
   438                          }}
   439                          styles={{
   440                              textInputContainer: [styles.flexColumn],
   441                              listView: [StyleUtils.getGoogleListViewStyle(displayListViewBorder), styles.borderLeft, styles.borderRight, !isFocused && styles.h0],
   442                              row: [styles.pv4, styles.ph3, styles.overflowAuto],
   443                              description: [styles.googleSearchText],
   444                              separator: [styles.googleSearchSeparator, styles.overflowAuto],
   445                              container: [styles.mh100],
   446                          }}
   447                          numberOfLines={2}
   448                          isRowScrollable={false}
   449                          listHoverColor={theme.border}
   450                          listUnderlayColor={theme.buttonPressedBG}
   451                          onLayout={(event: LayoutChangeEvent) => {
   452                              // We use the height of the element to determine if we should hide the border of the listView dropdown
   453                              // to prevent a lingering border when there are no address suggestions.
   454                              setDisplayListViewBorder(event.nativeEvent.layout.height > variables.googleEmptyListViewHeight);
